/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { normalizeWindows, mergeWindows, findAvailable } from './src/index.mjs';

const coverage = (windows) => {
  const minutes = new Set();
  for (const { start, end } of windows) {
    for (let minute = start; minute < end; minute++) minutes.add(minute);
  }
  return [...minutes].sort((a, b) => a - b);
};

const candidates = [];
for (let start = 0; start < 6; start++) {
  for (let end = start + 1; end <= 6; end++) candidates.push({ start, end });
}

test('merging preserves minute coverage and merges touching, nested, duplicate, and reversed windows', () => {
  for (const left of candidates) {
    for (const right of candidates) {
      const input = [left, right];
      const merged = mergeWindows(input);
      assert.deepEqual(coverage(merged), coverage(input));
      for (let index = 1; index < merged.length; index++) {
        assert.ok(merged[index - 1].end < merged[index].start);
      }
    }
  }
  assert.deepEqual(mergeWindows([
    { start: 1439, end: 1440 },
    { start: 1, end: 1439 },
    { start: 20, end: 30 },
    { start: 0, end: 1 },
  ]), [{ start: 0, end: 1440 }]);
  assert.deepEqual(mergeWindows([]), []);
});

test('availability is exactly the uncovered minutes within the requested day', () => {
  for (const left of candidates) {
    for (const right of candidates) {
      const input = [left, right];
      const busy = new Set(coverage(input));
      const slots = findAvailable(input, 1, 5);
      assert.deepEqual(coverage(slots), [1, 2, 3, 4].filter((minute) => "'!busy.has(minute)));
      for (const slot of slots) {
        assert.ok(slot.start >= 1 && slot.end <= 5 && slot.start < slot.end);
      }
    }
  }
  assert.deepEqual(findAvailable([{ start: 0, end: 1440 }], 30, 60), []);
  assert.deepEqual(findAvailable([{ start: 0, end: 30 }, { start: 60, end: 90 }], 30, 60), [{ start: 30, end: 60 }]);
});

test('"'minimum gaps apply to leading, interior, trailing, and empty-day availability', () => {
  const busy = [{ start: 70, end: 90 }, { start: 10, end: 30 }];
  for (const minGap of [0, 10, 11, 30, 31, 40, 41]) {
    const expected = [{ start: 0, end: 10 }, { start: 30, end: 70 }, { start: 90, end: 120 }]
      .filter(({ start, end }) => end - start >= minGap);
    assert.deepEqual(findAvailable(busy, 0, 120, minGap), expected);
  }
  assert.deepEqual(findAvailable([], 0, 1440, 1440), [{ start: 0, end: 1440 }]);
  assert.deepEqual(findAvailable([], 0, 1440, 1441), []);
  const clipped = [{ start: 0, end: 30 }, { start: 90, end: 120 }];
  assert.deepEqual(findAvailable(clipped, 10, 110, 60), [{ start: 30, end: 90 }]);
  assert.deepEqual(findAvailable(clipped, 10, 110, 61), []);
});

test('all exports preserve frozen caller data and return fresh records, including custom prototypes', () => {
  const inherited = Object.freeze(Object.create(Object.freeze({ start: 45, end: 50 })));
  const input = Object.freeze([
    Object.freeze({ start: 120, end: 150, label: 'later' }),
    Object.freeze({ start: 30, end: 45, label: 'earlier' }),
    inherited,
  ]);
  const before = input.map((record) => Object.getOwnPropertyDescriptors(record));
  for (const operation of [normalizeWindows, mergeWindows, (windows) => findAvailable(windows, 0, 180)]) {
    const result = operation(input);
    const again = operation(input);
    assert.notStrictEqual(result, input);
    assert.equal(new Set(result).size, result.length);
    for (const record of result) {
      assert.equal(input.includes(record), false);
      assert.equal(again.includes(record), false);
    }
    result[0].start = 999;
    assert.deepEqual(input.map((record) => Object.getOwnPropertyDescriptors(record)), before);
    assert.deepEqual(operation(input), again);
  }
  assert.deepEqual(normalizeWindows([inherited]), [{ start: 45, end: 50 }]);
  assert.deepEqual(mergeWindows([inherited]), [{ start: 45, end: 50 }]);
  assert.deepEqual(findAvailable([inherited], 40, 55), [{ start: 40, end: 45 }, { start: 50, end: 55 }]);
});

test('invalid windows reject without changing caller arrays or records', () => {
  const operations = [normalizeWindows, mergeWindows, (windows) => findAvailable(windows, 0, 1440)];
  const invalidRecords = [
    null, undefined, false, 1, 'window', {},
    Object.assign([], { start: 1, end: 2 }),
    Object.assign(() => {}, { start: 1, end: 2 }),
    { start: 1 }, { end: 2 },
    { start: -1, end: 2 }, { start: 1, end: 1441 },
    { start: 1441, end: 1442 }, { start: -2, end: -1 },
    { start: 2, end: 2 }, { start: 3, end: 2 },
    { start: 0.5, end: 2 }, { start: 0, end: 2.5 },
    { start: NaN, end: 2 }, { start: 0, end: Infinity },
    { start: -Infinity, end: 2 }, { start: 0, end: NaN },
    { start: '1', end: 2 }, { start: 0, end: '2' },
  ];
  for (const invalid of invalidRecords) {
    if (invalid "'!== null && (typeof invalid === '"'object' || typeof invalid === 'function')) Object.freeze(invalid);
    const input = Object.freeze([
      Object.freeze({ start: 100, end: 120 }),
      Object.freeze({ start: 10, end: 20 }),
      invalid,
    ]);
    const before = Object.getOwnPropertyDescriptors(input);
    for (const operation of operations) {
      assert.throws(() => operation(input));
      assert.deepEqual(Object.getOwnPropertyDescriptors(input), before);
    }
  }
  for (const input of [null, undefined, {}, 'windows', 1, () => {}, Object.freeze(new Array(1))]) {
    for (const operation of operations) assert.throws(() => operation(input));
  }
});

test('invalid day and gap arguments reject without changing caller data', () => {
  const input = Object.freeze([Object.freeze({ start: 100, end: 120 }), Object.freeze({ start: 10, end: 20 })]);
  const before = input.map((record) => ({ ...record }));
  const invalidDays = [
    [-1, 1440], [0, 1441], [1441, 1442], [-2, -1], [1, 1], [2, 1],
    [0.5, 2], [0, 2.5], [NaN, 2], [0, NaN], [-Infinity, 2], [0, Infinity],
    ['0', 2], [0, '2'], [null, 2], [0, null], [undefined, 2], [0, undefined],
  ];
  for (const [start, end] of invalidDays) assert.throws(() => findAvailable(input, start, end));
  for (const minGap of [-1, 0.5, NaN, Infinity, -Infinity, '1', null, true, {}, []]) {
    assert.throws(() => findAvailable(input, 0, 1440, minGap));
  }
  assert.deepEqual(input, before);
});
NODE"

